head.script:


            scwin.getType = function ( info ) {

                var rowIndex = info.rowIndex;
                var colIndex = info.colIndex;
                var returnInfo;


                if (dataList1.getCellData(rowIndex, "col1") == "select") {
					returnInfo = {
		                id : "dynamic_select_" + rowIndex + "_" + colIndex,
						inputType : "select",
						options : {
							viewType: "icon",
							chooseOption: "true",
							chooseOptionLabel: "-선택-"

						},
						itemSet : {
							nodeset : "data:dataList2",
							label : "col1",
							value : "col2"
						}
					};

                } else {
					returnInfo = {
		                id : "dynamic_text_" + rowIndex + "_" + colIndex,
						inputType : "text",
						options : {
							disabled:"true"
						}
					};


                }

                if(returnInfo) {
                   // console.log( "[typeGetter] (" + rowIndex + ", " + colIndex + ") : " +returnInfo.inputType);
                }

                return returnInfo;

			};



	scwin.onpageload = function() {
		var jsonData = [{"col1":"text","col2":"bb"},{"col1":"select","col2":"a1"},{"col1":"text","col2":"xxx"},{"col1":"text","col2":"xxx"}];
	    dataList1.setJSON( jsonData );


		var jsonData2 = [{"col1":"a1","col2":"a1"},{"col1":"a2","col2":"a2"},{"col1":"a3","col2":"a3"}];
	    dataList2.setJSON( jsonData2 );
	};

	scwin.onpageunload = function() {

	};

	scwin.grd_oncelldblclick = function(row,col,colId) {

		dataList1.removeRow(row);

		grd.refreshColumn( col);


	};

	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('grd_cell_3_1').parentNode.style.display == '';
	}
	scwin.unitTest = function() {
		//Unit test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_3_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_cell_3_1')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "300");
		//Run and Stop test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
